selector_to_html = {"a[href=\"#pyskyfire.ducts.orifice.OrificePlate.area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.area\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">area</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Bore area [m\u00b2].</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate.beta\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.beta\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">beta</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Diameter ratio, bore over pipe.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate.discharge_coefficient\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.discharge_coefficient\">\n<span class=\"sig-name descname\"><span class=\"pre\">discharge_coefficient</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">reynolds</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">density</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>The plate\u2019s discharge coefficient at a pipe Reynolds number.</p><p>A supplied <code class=\"docutils literal notranslate\"><span class=\"pre\">cd</span></code> is returned as it is. Otherwise this is\nReader-Harris/Gallagher, which depends only on the Reynolds number\nand geometry; <code class=\"docutils literal notranslate\"><span class=\"pre\">density</span></code> does not change the result.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate._check_range\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate._check_range\">\n<span class=\"sig-name descname\"><span class=\"pre\">_check_range</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">reynolds</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OrificePlate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pipe_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">orifice_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">taps</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'flange'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A thin round orifice plate in a straight pipe.</p><p class=\"rubric\">Notes</p><p>The flow follows ISO 5167,\n<span class=\"math notranslate nohighlight\">\\(\\dot m = C \\varepsilon A \\sqrt{2 \\rho_1 \\Delta p / (1 - \\beta^4)}\\)</span>,\nwith <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.OrificePlate.expansibility\" title=\"pyskyfire.ducts.orifice.OrificePlate.expansibility\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">expansibility()</span></code></a> for \u03b5. That \u03b5 is fitted to thin plates, whose\njet keeps contracting past the bore, and it is not the isentropic nozzle\nexpansion <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Orifice</span></code> uses: for a gas at a 2.5 % tap drop the\nnozzle expansion would overstate the drop by about 1.6 %.</p><p>The permanent loss is ISO 5167-1\u2019s recovery relation,</p></dd>", "a[href=\"#pyskyfire-ducts-orifice-orificeplate\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.orifice.OrificePlate<a class=\"headerlink\" href=\"#pyskyfire-ducts-orifice-orificeplate\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">viscosity</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"OrificePlateResult.html#pyskyfire.ducts.orifice.OrificePlateResult\" title=\"pyskyfire.ducts.orifice.OrificePlateResult\"><span class=\"pre\">OrificePlateResult</span></a></span></span></dt><dd><p>The tap-to-tap drop and permanent loss at <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code>.</p></dd>", "a[href=\"../../thermo/eos/EquationOfState.html#pyskyfire.thermo.eos.EquationOfState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.EquationOfState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.eos.</span></span><span class=\"sig-name descname\"><span class=\"pre\">EquationOfState</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>The state lookups a machine design asks of a fluid.</p><p>Every pressure is in Pa, temperature in K and specific enthalpy in\nJ kg\u207b\u00b9. Enthalpy is only ever compared with enthalpy from the same\nequation of state, so its datum does not matter.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate._viscosity\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate._viscosity\">\n<span class=\"sig-name descname\"><span class=\"pre\">_viscosity</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">eos</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">viscosity</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"OrificePlateResult.html#pyskyfire.ducts.orifice.OrificePlateResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlateResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OrificePlateResult</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">OrificeResult</span></code></p><p>An <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">OrificeResult</span></code> with the plate\u2019s metering quantities.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">throat_state</span></code> is at the downstream tap, and\n<a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.OrificePlateResult.differential_pressure\" title=\"pyskyfire.ducts.orifice.OrificePlateResult.differential_pressure\"><code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">differential_pressure</span></code></a> is the tap-to-tap drop a flow meter reads.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">outlet_state</span></code> is where the flow has recovered to the pipe bore, so\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">pressure_loss</span></code> is the permanent loss, which is smaller.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate.permanent_loss_fraction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.permanent_loss_fraction\">\n<span class=\"sig-name descname\"><span class=\"pre\">permanent_loss_fraction</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Permanent loss over tap-to-tap drop, from ISO 5167-1.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.OrificePlate.expansibility\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.expansibility\">\n<span class=\"sig-name descname\"><span class=\"pre\">expansibility</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">eos</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/eos/EquationOfState.html#pyskyfire.thermo.eos.EquationOfState\" title=\"pyskyfire.thermo.eos.EquationOfState\"><span class=\"pre\">EquationOfState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_tap</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>ISO 5167-2\u2019s expansibility factor, \u03b5, between the taps.</p><p>The isentropic exponent is the secant <code class=\"docutils literal notranslate\"><span class=\"pre\">ln(p1/p2)/ln(\u03c11/\u03c12)</span></code> along\nthe isentrope between the tap pressures, so it applies to real\nfluids, and a constant density gives \u03b5 = 1.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
